import{_ as l,o as t,c as r,a2 as o}from"./chunks/framework.BV21bweQ.js";const c=JSON.parse('{"title":"共同体时期","description":"","frontmatter":{},"headers":[],"relativePath":"表层/历史/共同体时期.md","filePath":"表层/历史/共同体时期.md","lastUpdated":1787066340000}'),e={name:"表层/历史/共同体时期.md"};function i(h,a,n,s,u,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="共同体时期" tabindex="-1">共同体时期 <a class="header-anchor" href="#共同体时期" aria-label="Permalink to &quot;共同体时期&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>共同体时期指神明&quot;红星&quot;降临、带领大陆智慧生灵脱离蒙昧并建立&quot;共同体&quot;的时期，是福瑞文明有记载历史的开端。自建国元年起，至约建国200年共同体解体、黑暗时代开启为止，历时约两百年。</p><h2 id="建国初期" tabindex="-1">建国初期 <a class="header-anchor" href="#建国初期" aria-label="Permalink to &quot;建国初期&quot;">​</a></h2><h3 id="神明降临与共同体建立" tabindex="-1">神明降临与共同体建立 <a class="header-anchor" href="#神明降临与共同体建立" aria-label="Permalink to &quot;神明降临与共同体建立&quot;">​</a></h3><p>在智慧生灵仍处于部落蒙昧状态时，一位自称&quot;红星&quot;的神明降临世间。他主动接触各族部落，展示神迹，引导生灵脱离蒙昧、步入文明。</p><p>神明带领各族建立&quot;共同体&quot;，并赋予所有成员统一的身份——&quot;共同体公民&quot;，打破了各族之间的隔阂。此后的记载中，各族生灵统称其为&quot;红星&quot;或&quot;神明&quot;。</p><h3 id="梯形神殿" tabindex="-1">梯形神殿 <a class="header-anchor" href="#梯形神殿" aria-label="Permalink to &quot;梯形神殿&quot;">​</a></h3><p>建国初期，共同体建成梯形神殿：</p><ul><li>共同体的政治与行政中心</li><li>神明的正式居所与工作场所</li><li>神明投影系统启用，神明可借此与各地民众交流</li><li>共同体的核心象征</li></ul><h3 id="五大主族分工" tabindex="-1">五大主族分工 <a class="header-anchor" href="#五大主族分工" aria-label="Permalink to &quot;五大主族分工&quot;">​</a></h3><p>神明根据各族特质分配任务，确立社会分工：</p><ul><li><strong>牛族</strong>：负责农业相关事务</li><li><strong>鹿族</strong>：负责科研相关事务</li><li><strong>熊族</strong>：负责工业相关事务</li><li><strong>鹤族</strong>：负责政治相关事务</li><li><strong>甲族</strong>：负责军事相关事务</li></ul><p>共同体时期的种族不止五个，鸽族、鹰族、狮族等其余种族亦在共同体之中，共同构成共同体社会。</p><h2 id="重要时间节点" tabindex="-1">重要时间节点 <a class="header-anchor" href="#重要时间节点" aria-label="Permalink to &quot;重要时间节点&quot;">​</a></h2><ul><li><strong>建国22年——&quot;天穹破碎&quot;事件</strong>：神明的神环首次清晰地向世人显现。那是一道红色为主、边缘泛金的六边形光环，被中心对称地分为三份，大量民众亲眼目睹。</li><li><strong>建国50年</strong>：在神明点拨与鹿族研究下，蒸汽机车成功运行，交通与工业基础由此奠定。</li><li><strong>建国62年</strong>：一位鹿族学者以白糖混合土硝进行实验引发爆炸。神明与其长谈后，学者主动放弃研究，称&quot;神明说得对，现在不是时候&quot;。</li><li><strong>建国100年</strong>：在神明点拨与鹿族研究下，电灯问世，电子技术取得突破。</li><li><strong>建国120年</strong>：在蒸汽与内燃机理论趋于饱和时，神明递给鹿族学者一枚&quot;单向导电的电子元件&quot;，直接开启了电子技术的大门；此后无线电、电报等现代通讯技术迅速普及。</li><li><strong>建国154年</strong>：神明突访鹿族科学院，下令封锁粒子物理系，带走相关学者与数据。解封后，一名核心学者及其团队彻底消失。神明对此解释道：&quot;知识不应变成武器，尤其是这些……至少现在不应该。&quot;</li><li><strong>建国171年</strong>：地脉异常开始。</li></ul><h2 id="地脉异常与灾难" tabindex="-1">地脉异常与灾难 <a class="header-anchor" href="#地脉异常与灾难" aria-label="Permalink to &quot;地脉异常与灾难&quot;">​</a></h2><h3 id="地脉" tabindex="-1">地脉 <a class="header-anchor" href="#地脉" aria-label="Permalink to &quot;地脉&quot;">​</a></h3><p>大陆地表存在名为&quot;地脉&quot;的现象——从地面上呈线性冒出的白色光芒，亮度不一，相互连通。神明曾警示：&quot;尽量远离地脉，不要在地脉上修建东西，那是大地的伤口，而且并没有愈合。&quot;</p><h3 id="异常前兆-建国171年起" tabindex="-1">异常前兆（建国171年起） <a class="header-anchor" href="#异常前兆-建国171年起" aria-label="Permalink to &quot;异常前兆（建国171年起）&quot;">​</a></h3><ul><li>地脉光芒亮度明显增加，逐渐有了宽度</li><li>地表出现数毫米至数厘米不定的高低差</li></ul><h3 id="神明失踪" tabindex="-1">神明失踪 <a class="header-anchor" href="#神明失踪" aria-label="Permalink to &quot;神明失踪&quot;">​</a></h3><p>异常期间，空中降下金色光柱，将神明带往不知何处。不到一个下午，神明返回，面色凝重。</p><h3 id="权力移交鹤族" tabindex="-1">权力移交鹤族 <a class="header-anchor" href="#权力移交鹤族" aria-label="Permalink to &quot;权力移交鹤族&quot;">​</a></h3><p>因长期处理地脉问题，神明已将部分管理权移交鹤族。然而鹤族的执政并不顺利：</p><ul><li><strong>威信不足</strong>：鹤族虽有理论知识，但缺乏顶层实践经验，民众普遍抱怨&quot;鹤族的管理远不如神明&quot;</li><li><strong>决策瘫痪</strong>：高层决策因无法服众而陷入停滞，只能等待神明回归处理，社会问题逐渐积压</li></ul><h3 id="甲族动员-建国171年年末" tabindex="-1">甲族动员（建国171年年末） <a class="header-anchor" href="#甲族动员-建国171年年末" aria-label="Permalink to &quot;甲族动员（建国171年年末）&quot;">​</a></h3><p>神明召集甲族将领，告知灾难即将降临，需要甲族作为最后的防线。甲族团结一致，无畏牺牲。</p><h3 id="灾难爆发" tabindex="-1">灾难爆发 <a class="header-anchor" href="#灾难爆发" aria-label="Permalink to &quot;灾难爆发&quot;">​</a></h3><p>地脉毫无征兆地爆发涌动，主要力量直奔神明。甲族拼尽全力拦截余波，却未能完全阻挡。神明本体被地脉吞没，暂时失去意识，漂浮于神殿中央，陷入昏迷。</p><h2 id="神明昏迷之后" tabindex="-1">神明昏迷之后 <a class="header-anchor" href="#神明昏迷之后" aria-label="Permalink to &quot;神明昏迷之后&quot;">​</a></h2><h3 id="鹿族的-神明复活计划" tabindex="-1">鹿族的&quot;神明复活计划&quot; <a class="header-anchor" href="#鹿族的-神明复活计划" aria-label="Permalink to &quot;鹿族的&quot;神明复活计划&quot;&quot;">​</a></h3><p>神明昏迷后，共同体陷入领导真空。鹤族公信力不足，鹿族作为主族之首独揽大权，举国主导&quot;神明复活计划&quot;，试图唤醒神明。</p><p>实验发生严重事故：</p><ul><li>以神明躯体为中心的地脉能量瞬间暴走</li><li>梯形神殿被炸翻</li><li>首都区域地面严重下沉</li><li>河水涌入，短短数日内，繁华的首都彻底沦为<strong>水下之城</strong></li></ul><p>此次事故引发第二次地脉灾难，甲族损失惨重，共同体基础设施几近崩断。</p><h3 id="政治格局变化" tabindex="-1">政治格局变化 <a class="header-anchor" href="#政治格局变化" aria-label="Permalink to &quot;政治格局变化&quot;">​</a></h3><ul><li>鹿族因实验事故的责任，彻底失去主导地位</li><li>政权变为鹿、熊、牛、甲四族平级</li><li>鹤族继续被架空，无实际权力</li><li>鹰族逐渐从底层崛起，掌握舆论话语权，逐渐架空五大主族，完成事实上的公信力转移</li></ul><h2 id="甲族之灭" tabindex="-1">甲族之灭 <a class="header-anchor" href="#甲族之灭" aria-label="Permalink to &quot;甲族之灭&quot;">​</a></h2><p>共同体末期，甲族近乎灭绝，幸存者屈指可数。至于灭绝的原因，官方记载一片空白，民间则众说纷纭。时至今日，仍无人能说清当年究竟发生了什么。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></p></blockquote><h2 id="法师的出现与共同体解体" tabindex="-1">法师的出现与共同体解体 <a class="header-anchor" href="#法师的出现与共同体解体" aria-label="Permalink to &quot;法师的出现与共同体解体&quot;">​</a></h2><h3 id="法师时代" tabindex="-1">法师时代 <a class="header-anchor" href="#法师时代" aria-label="Permalink to &quot;法师时代&quot;">​</a></h3><p>地脉灾难后，大陆上常有具备超自然力量的个体出现，众人将其称为传说中的<strong>法师</strong>，并将其力量称为传说中的<strong>魔法</strong>。法师数量逐渐增多，形成法师阶级，逐渐改变了共同体的权力结构，共同体渐渐名存实亡。</p><h3 id="黑暗时代开启" tabindex="-1">黑暗时代开启 <a class="header-anchor" href="#黑暗时代开启" aria-label="Permalink to &quot;黑暗时代开启&quot;">​</a></h3><p>约建国200年，共同体正式解体。在鹰族代表的宣布下，共同体分裂为数个法师封地。猪族、蝠族、豹族、虎族与鹰族合并组成新五族统治，黑暗时代自此开启。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></p></li><li><p><a href="./../../中层/世界/地脉与魔法" class="layer-link" data-layer="中层">地脉与魔法</a></p></li><li><p><a href="./黑暗时代">黑暗时代</a></p></li><li><p><a href="./当前时代">当前时代</a></p></li><li><p><a href="./../../中层/人物/维斯塔" class="layer-link" data-layer="中层">维斯塔</a></p></li><li><p><a href="./../种族/五大主族总览">五大主族总览</a></p></li></ul><hr>',50)])])}const p=l(e,[["render",i]]);export{c as __pageData,p as default};
